import re
from datetime import datetime

_DISPLAY_NAME_RE = re.compile(r"<([^<>]*)>")
_PHONE_EXT_RE = re.compile(r"x|ext|#")
_ZIP_PLUS4_RE = re.compile(r"([0-9]+)-[0-9]{4}")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_TAG_SPLIT_RE = re.compile(r"[;,]")


def _normalize_email(raw):
    s = raw
    m = _DISPLAY_NAME_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    local, sep, domain = s.partition("@")
    if sep and domain in ("gmail.com", "googlemail.com"):
        local = local.replace(".", "")
        local = local.split("+", 1)[0]
        s = f"{local}@gmail.com"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = raw.lower()
    m = _PHONE_EXT_RE.search(s)
    if m:
        s = s[:m.start()]
    digits = re.sub(r"[^0-9]", "", s)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    z = raw.strip()
    m = _ZIP_PLUS4_RE.fullmatch(z)
    if m:
        z = m.group(1)
    if re.fullmatch(r"[0-9]{4}", z):
        z = "0" + z
    if not re.fullmatch(r"[0-9]{5}", z):
        return ""
    return z


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _is_opted_out(raw):
    return raw.strip().lower() in _OPT_OUT_VALUES


def _parse_tags(raw):
    return {t.strip().lower() for t in _TAG_SPLIT_RE.split(raw) if t.strip()}


def _pick(members, field):
    """Pick the normalized value of `field` from the best row where it is non-empty.

    Preference: manual source, then most recent updated, then earliest input row.
    """
    cands = [m for m in members if m[field]]
    if not cands:
        return ""
    best = max(cands, key=lambda m: (m["manual"], m["updated"], -m["idx"]))
    return best[field]


def _merge_group(members):
    latest = max(m["updated"] for m in members)
    tags = set().union(*(m["tags"] for m in members))
    return {
        "first_name": _pick(members, "first_name"),
        "last_name": _pick(members, "last_name"),
        "zip": _pick(members, "zip"),
        "email": _pick(members, "email"),
        "phone": _pick(members, "phone"),
        "source": _pick(members, "source"),
        "tags": ";".join(sorted(tags)),
        "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
        "updated": latest.strftime("%Y-%m-%d"),
    }


def dedupe_contacts(rows):
    # Step 1: normalize every row and drop rows with no valid email or phone.
    records = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        phone = _normalize_phone(row.get("phone", ""))
        rec = {
            "idx": idx,
            "first_name": _normalize_name(row.get("first_name", "")),
            "last_name": _normalize_name(row.get("last_name", "")),
            "zip": _normalize_zip(row.get("zip", "")),
            "email": email if _is_valid_email(email) else "",
            "phone": phone if _is_valid_phone(phone) else "",
            "source": row.get("source", "").strip().lower(),
            "tags": _parse_tags(row.get("tags", "")),
            "opted_out": _is_opted_out(row.get("opted_out", "")),
            "updated": _parse_updated(row["updated"]),
        }
        if not rec["email"] and not rec["phone"]:
            continue
        rec["manual"] = rec["source"] == "manual"
        records.append(rec)

    # Step 2: group matching rows with union-find. Two rows match if they share
    # a valid email, or a valid phone plus a non-empty last name. Indexing by
    # these keys gives the same transitive grouping as comparing every pair.
    parent = list(range(len(records)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_by_email = {}
    first_by_phone_last = {}
    for i, rec in enumerate(records):
        if rec["email"]:
            if rec["email"] in first_by_email:
                union(i, first_by_email[rec["email"]])
            else:
                first_by_email[rec["email"]] = i
        last = rec["last_name"].lower()
        if rec["phone"] and last:
            key = (rec["phone"], last)
            if key in first_by_phone_last:
                union(i, first_by_phone_last[key])
            else:
                first_by_phone_last[key] = i

    # Step 3: collect groups. Records are in input order, so groups appear
    # ordered by their earliest row.
    groups = {}
    for i, rec in enumerate(records):
        groups.setdefault(find(i), []).append(rec)

    return [_merge_group(members) for members in groups.values()]
```

Interpretation notes for the data person:

- **Extension marker:** the cut happens at the earliest "x", "ext", or "#" anywhere in the phone string.
- **ZIP+4:** any digits followed by a hyphen and four digits are treated as ZIP+4, so "2139-4307" becomes "02139".
- **Malformed `updated`:** the function raises `ValueError` rather than guessing. That makes a bad date in the export visible before the email goes out.
- **Performance:** matching uses dictionary lookups, so it runs in linear time on the export size.
